```json
{
  "root_causes": [
    {
      "service": "ts-travel2-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('Travel2Controller.getRouteByTripId','Travel2Controller.queryInfo','Travel2Controller.getTripAllDetailInfo','TripRepository.findByRouteId','TripRepository.findAll','SELECT Trip') GROUP BY 1 ORDER BY 1",
          "claim": "travel2 controller methods take seconds (p50 ~3.7s to ~11s) while their child DB spans stay around 1-3 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms FROM normal_traces WHERE service_name='ts-travel2-service' AND span_name IN ('Travel2Controller.getRouteByTripId','Travel2Controller.queryInfo') GROUP BY 1,2",
          "claim": "In the normal period the same travel2 controller methods ran in about 11 ms and 86 ms at p50."
        },
        {
          "kind": "metric",
          "sql": "SELECT metric, avg(value) v FROM abnormal_metrics WHERE service_name='ts-travel2-service' AND metric IN ('container.cpu.usage','k8s.pod.cpu.usage','container.memory.usage') GROUP BY 1",
          "claim": "travel2 container CPU and memory stay low or normal, so the slowness is not resource saturation."
        }
      ]
    },
    {
      "service": "ts-contacts-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT span_name, attr_span_kind, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='ts-contacts-service' AND span_name IN ('ContactsRepository.findById','SELECT ts.contacts','Session.find contacts.entity.Contacts') GROUP BY 1,2 ORDER BY 1",
          "claim": "ContactsRepository.findById p95 is about 1.27s while its SQL and session spans stay around 1 ms."
        },
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 callee_server_p95_ms, approx_quantile(p.duration,0.95)/1e6 caller_client_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-preserve-service' AND c.service_name='ts-contacts-service' GROUP BY 1,2",
          "claim": "Preserve's client calls to contacts show the same ~1.28s p95 as contacts' server spans."
        }
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel2-service",
      "to": "ts-route-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_server_p50_ms, approx_quantile(c.duration,0.95)/1e6 callee_server_p95_ms, approx_quantile(p.duration,0.95)/1e6 caller_client_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-route-plan-service' AND c.service_name='ts-travel2-service' GROUP BY 1,2",
          "claim": "Route-plan's client calls to travel2 take about 3.7s at p50, matching travel2's slow server spans."
        }
      ]
    },
    {
      "from": "ts-route-plan-service",
      "to": "ts-travel-plan-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration,0.5)/1e6 callee_server_p50_ms, approx_quantile(c.duration,0.95)/1e6 callee_server_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-travel-plan-service' AND c.service_name='ts-route-plan-service' GROUP BY 1,2",
          "claim": "Travel-plan's calls to route-plan take about 14.9s at p50, inheriting route-plan's slowness from travel2."
        }
      ]
    },
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 callee_server_p95_ms, approx_quantile(p.duration,0.95)/1e6 caller_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE p.service_name='ts-ui-dashboard' AND c.service_name='ts-travel-plan-service' AND c.attr_span_kind='Server' GROUP BY 1,2",
          "claim": "Dashboard's calls to travel-plan reach about 26s at p95, so user travel-plan requests are slow."
        }
      ]
    },
    {
      "from": "ts-contacts-service",
      "to": "ts-preserve-service",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT p.service_name AS caller, c.service_name AS callee, count(*) n, approx_quantile(c.duration,0.95)/1e6 callee_server_p95_ms, approx_quantile(p.duration,0.95)/1e6 caller_client_p95_ms FROM abnormal_traces c JOIN abnormal_traces p ON c.parent_span_id = p.span_id AND c.trace_id = p.trace_id WHERE c.attr_span_kind='Server' AND p.attr_span_kind='Client' AND p.service_name='ts-preserve-service' AND c.service_name='ts-contacts-service' GROUP BY 1,2",
          "claim": "Preserve's client calls to contacts take about 1.29s at p95, and preserve's own latency rises with them."
        }
      ]
    },
    {
      "from": "ts-preserve-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {
          "kind": "trace",
          "sql": "SELECT service_name, span_name, count(*) n, approx_quantile(duration,0.5)/1e6 p50ms, approx_quantile(duration,0.95)/1e6 p95ms FROM abnormal_traces WHERE service_name='ts-preserve-service' AND span_name='POST /api/v1/preserveservice/preserve' GROUP BY 1,2",
          "claim": "Preserve's user-facing POST /preserve p95 rises to about 1.76s, versus about 1.09s in normal."
        }
      ]
    }
  ]
}
